#include <bits/stdc++.h>
using namespace std;

struct State {
    int kr, kc; // top-left of king (2x2)
    vector<pair<int,int>> pawns; // 1x1 pawns
    bool operator==(const State &o) const {
        return kr == o.kr && kc == o.kc && pawns == o.pawns;
    }
};

struct StateHash {
    size_t operator()(const State &s) const {
        size_t h = hash<int>()(s.kr) ^ (hash<int>()(s.kc) << 1);
        for (auto &p : s.pawns)
            h ^= hash<int>()(p.first) ^ (hash<int>()(p.second) << 1);
        return h;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    cin >> R >> C;
    vector<string> grid(R);
    for (int i = 0; i < R; i++) cin >> grid[i];

    State start;
    start.kr = start.kc = -1;
    vector<pair<int,int>> pawns;
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            if (grid[r][c] == 'K') {
                start.kr = r;
                start.kc = c;
            } else if (grid[r][c] == 'P') {
                pawns.push_back({r, c});
            }
        }
    }
    start.pawns = pawns;

    // BFS
    unordered_map<State, int, StateHash> dist;
    queue<State> q;
    dist[start] = 0;
    q.push(start);

    // directions for king and pawns (4-directional)
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    auto is_free = [&](int r, int c, const State &s) -> bool {
        if (r < 0 || r >= R || c < 0 || c >= C) return false;
        if (grid[r][c] == '#') return false;
        // check king cells
        if (r >= s.kr && r < s.kr+2 && c >= s.kc && c < s.kc+2) return false;
        // check pawns
        for (auto &p : s.pawns) if (p.first == r && p.second == c) return false;
        return true;
    };

    while (!q.empty()) {
        State cur = q.front(); q.pop();
        int d = dist[cur];

        // King moves
        for (int dir = 0; dir < 4; dir++) {
            int nkr = cur.kr + dr[dir];
            int nkc = cur.kc + dc[dir];
            // Check if king fits in bounds and all 4 cells free
            bool ok = true;
            for (int rr = nkr; rr < nkr+2 && ok; rr++) {
                for (int cc = nkc; cc < nkc+2 && ok; cc++) {
                    if (!is_free(rr, cc, cur)) ok = false;
                }
            }
            if (!ok) continue;
            State ns = cur;
            ns.kr = nkr;
            ns.kc = nkc;
            if (dist.find(ns) == dist.end()) {
                dist[ns] = d+1;
                q.push(ns);
            }
        }

        // Pawn moves
        for (int i = 0; i < (int)cur.pawns.size(); i++) {
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.pawns[i].first + dr[dir];
                int nc = cur.pawns[i].second + dc[dir];
                if (!is_free(nr, nc, cur)) continue;
                State ns = cur;
                ns.pawns[i] = {nr, nc};
                sort(ns.pawns.begin(), ns.pawns.end()); // canonical order
                if (dist.find(ns) == dist.end()) {
                    dist[ns] = d+1;
                    q.push(ns);
                }
            }
        }
    }

    // Goal: king at (0,0)
    State goal;
    goal.kr = 0;
    goal.kc = 0;
    goal.pawns = start.pawns; // same pawns, order doesn't matter for hash
    sort(goal.pawns.begin(), goal.pawns.end());

    if (dist.find(goal) != dist.end()) {
        cout << dist[goal] << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
State compression for a 5x4 board (20 cells).
Pieces:
- One 2x2 king, marked '1' in input.
- Several 1x1 pawns, marked 'o' in input.
- Obstacles/walls, marked 'x' in input.
- Empty cells, marked '.' in input.

A move:
- A pawn moves one step into an orthogonally adjacent empty cell.
- The king moves one step (up/down/left/right) if the entire shifted 2x2 area is free
  except for the king's current cells.

Goal:
- Move the king to the upper-left corner, i.e. occupy cells (0,0),(0,1),(1,0),(1,1).

We perform BFS on states.
A state is determined by:
- king top-left position (kr, kc)
- set of pawn cells
Obstacles are fixed.

Encoding:
- 20-bit mask for pawns
- king position encoded separately (0..19 top-left valid only where 2x2 fits)
Visited key is uint32_t: pawnMask | (kingPos << 20)
*/

static const int H = 5, W = 4;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> g(H);
    for (int i = 0; i < H; ++i) {
        if (!(cin >> g[i])) return 0;
    }

    int obstacleMask = 0;
    int pawnMask = 0;
    int kr = -1, kc = -1;

    auto id = [&](int r, int c) { return r * W + c; };

    // Find king's top-left and masks
    vector<pair<int,int>> kingCells;
    for (int r = 0; r < H; ++r) {
        for (int c = 0; c < W; ++c) {
            char ch = g[r][c];
            if (ch == 'x') obstacleMask |= (1 << id(r, c));
            else if (ch == 'o') pawnMask |= (1 << id(r, c));
            else if (ch == '1') kingCells.push_back({r, c});
        }
    }

    if (kingCells.size() != 4) return 0;

    kr = H, kc = W;
    for (auto [r, c] : kingCells) {
        kr = min(kr, r);
        kc = min(kc, c);
    }

    auto kingMaskFrom = [&](int r, int c) -> int {
        return (1 << id(r, c)) |
               (1 << id(r, c + 1)) |
               (1 << id(r + 1, c)) |
               (1 << id(r + 1, c + 1));
    };

    auto validKingPos = [&](int r, int c) -> bool {
        if (r < 0 || c < 0 || r + 1 >= H || c + 1 >= W) return false;
        int km = kingMaskFrom(r, c);
        return (km & obstacleMask) == 0;
    };

    if (!validKingPos(kr, kc)) return 0;

    auto encode = [&](int r, int c, int pmask) -> uint32_t {
        return (uint32_t)pmask | ((uint32_t)id(r, c) << 20);
    };

    queue<tuple<int,int,int,int>> q; // kr, kc, pawnMask, dist
    unordered_set<uint32_t> vis;

    uint32_t startKey = encode(kr, kc, pawnMask);
    vis.insert(startKey);
    q.push({kr, kc, pawnMask, 0});

    while (!q.empty()) {
        auto [r, c, pm, dist] = q.front();
        q.pop();

        if (r == 0 && c == 0) {
            cout << dist << '\n';
            return 0;
        }

        int km = kingMaskFrom(r, c);
        int occ = obstacleMask | pm | km;

        // Move pawns
        for (int cell = 0; cell < H * W; ++cell) {
            if (!(pm & (1 << cell))) continue;
            int pr = cell / W, pc = cell % W;

            static int dr[4] = {-1, 1, 0, 0};
            static int dc[4] = {0, 0, -1, 1};

            for (int d = 0; d < 4; ++d) {
                int nr = pr + dr[d], nc = pc + dc[d];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                int to = id(nr, nc);
                if (occ & (1 << to)) continue;

                int npm = pm;
                npm ^= (1 << cell);
                npm |= (1 << to);

                uint32_t key = encode(r, c, npm);
                if (!vis.count(key)) {
                    vis.insert(key);
                    q.push({r, c, npm, dist + 1});
                }
            }
        }

        // Move king
        static int drk[4] = {-1, 1, 0, 0};
        static int dck[4] = {0, 0, -1, 1};
        for (int d = 0; d < 4; ++d) {
            int nr = r + drk[d], nc = c + dck[d];
            if (!validKingPos(nr, nc)) continue;

            int nkm = kingMaskFrom(nr, nc);
            // New king cells must not overlap pawns or obstacles,
            // ignoring current king cells since the king moves away from them.
            if ((nkm & obstacleMask) != 0) continue;
            if ((nkm & pm) != 0) continue;

            uint32_t key = encode(nr, nc, pm);
            if (!vis.count(key)) {
                vis.insert(key);
                q.push({nr, nc, pm, dist + 1});
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

