import sys

def solve():
    input_data = sys.stdin.read().strip().splitlines()
    if not input_data:
        return
    H, W = map(int, input_data[0].split())
    grid = [list(row.rstrip()) for row in input_data[1:1+H]]

    # Find pieces
    king_pos = None
    pawns = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'K':
                # King is 2x2, top-left corner
                king_pos = (r, c)
            elif grid[r][c] == 'P':
                pawns.append((r, c))

    initial_pawns = tuple(sorted(pawns))
    start = (king_pos, initial_pawns)

    # Goal: king at (0,0)
    goal_king = (0, 0)

    # Directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # BFS
    visited = set()
    q = deque()
    visited.add(start)
    q.append((king_pos, initial_pawns, 0))

    while q:
        (kr, kc), pawns_list, dist = q.popleft()

        if (kr, kc) == goal_king:
            print(dist)
            return

        # Build set of occupied cells
        occupied = set()
        for dr in range(2):
            for dc in range(2):
                occupied.add((kr+dr, kc+dc))
        for pr, pc in pawns_list:
            occupied.add((pr, pc))

        # Determine empty cells
        empties = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] != '#' and (r, c) not in occupied:
                    empties.append((r, c))

        # Try moving king
        for dr, dc in dirs:
            nkr, nkc = kr + dr, kc + dc
            if nkr < 0 or nkr+2 > H or nkc < 0 or nkc+2 > W:
                continue
            # check if new king cells are free
            free = True
            for ddr in range(2):
                for ddc in range(2):
                    nr, nc = nkr+ddr, nkc+ddc
                    if grid[nr][nc] == '#':
                        free = False
                        break
                if not free:
                    break
            if not free:
                continue
            # Check overlap with pawns
            king_cells = set()
            for ddr in range(2):
                for ddc in range(2):
                    king_cells.add((nkr+ddr, nkc+ddc))
            if king_cells & set(pawns_list):
                continue

            new_state = ((nkr, nkc), pawns_list)
            if new_state not in visited:
                visited.add(new_state)
                q.append((new_state[0], new_state[1], dist+1))

        # Try moving each pawn
        for i, (pr, pc) in enumerate(pawns_list):
            for dr, dc in dirs:
                npr, npc = pr + dr, pc + dc
                if npr < 0 or npr >= H or npc < 0 or npc >= W:
                    continue
                if grid[npr][npc] == '#':
                    continue
                # check no overlap
                if (npr, npc) in occupied:
                    continue
                new_pawns = list(pawns_list)
                new_pawns[i] = (npr, npc)
                new_pawns.sort()
                new_state = (king_pos, tuple(new_pawns))
                if new_state not in visited:
                    visited.add(new_state)
                    q.append((new_state[0], new_state[1], dist+1))

    print(-1)

