from collections import deque
import sys

def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0
    while idx < len(input_data) and input_data[idx].strip() == '':
        idx += 1

    # Read grid
    grid_lines = []
    while idx < len(input_data):
        line = input_data[idx]
        idx += 1
        if line.strip() == '' and grid_lines:
            break
        if line.strip():
            grid_lines.append(line.rstrip())

    rows = len(grid_lines)
    cols = max(len(l) for l in grid_lines)

    # Parse grid
    obstacles = set()
    king_pos = None
    pawns = []

    for r, line in enumerate(grid_lines):
        for c, ch in enumerate(line):
            if ch == '#':
                obstacles.add((r, c))
            elif ch == 'K':
                # Could be multiple K cells - find top-left
                if king_pos is None or (r < king_pos[0]) or (r == king_pos[0] and c < king_pos[1]):
                    king_pos = (r, c)
            elif ch == 'P':
                pawns.append((r, c))

    # Remove duplicate pawns (King occupies 4 cells, pawns are individual)
    # King occupies king_pos, king_pos+(0,1), king_pos+(1,0), king_pos+(1,1)
    pawn_set = set(pawns)
    # Remove king cells from pawns
    if king_pos:
        for dr in range(2):
            for dc in range(2):
                pawn_set.discard((king_pos[0]+dr, king_pos[1]+dc))

    pawns = tuple(sorted(pawn_set))

    initial_state = (king_pos, pawns)
    goal_king = (0, 0)

    def get_occupied(king, pawns_t):
        occ = set()
        for dr in range(2):
            for dc in range(2):
                occ.add((king[0]+dr, king[1]+dc))
        for p in pawns_t:
            occ.add(p)
        return occ

    def valid_king(r, c, occ_without_king):
        for dr in range(2):
            for dc in range(2):
                nr, nc = r+dr, c+dc
                if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                    return False
                if (nr, nc) in obstacles:
                    return False
                if (nr, nc) in occ_without_king:
                    return False
        return True

    queue = deque([(initial_state, 0)])
    visited = {initial_state}

    while queue:
        (king, pawns_t), moves = queue.popleft()

        if king == goal_king:
            print(moves)
            return

        occ = get_occupied(king, pawns_t)
        king_cells = {(king[0]+dr, king[1]+dc) for dr in range(2) for dc in range(2)}
        occ_no_king = occ - king_cells

        # Move king
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nkr, nkc = king[0]+dr, king[1]+dc
            if valid_king(nkr, nkc, occ_no_king):
                ns = ((nkr, nkc), pawns_t)
                if ns not in visited:
                    visited.add(ns)
                    queue.append((ns, moves+1))

        # Move each pawn
        for i, (pr, pc) in enumerate(pawns_t):
            occ_no_pawn = occ - {(pr, pc)}
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                npr, npc = pr+dr, pc+dc
                if 0 <= npr < rows and 0 <= npc < cols and (npr,npc) not in obstacles and (npr,npc) not in occ_no_pawn:
                    new_pawns = tuple(sorted(pawns_t[:i] + ((npr,npc),) + pawns_t[i+1:]))
                    ns = (king, new_pawns)
                    if ns not in visited:
                        visited.add(ns)
                        queue.append((ns, moves+1))

    print(-1)

