import java.util.*;

public class SlidingKingPuzzle {
    static int H, W;
    static char[][] board;
    static int[] dr = { -1, 1, 0, 0 };
    static int[] dc = { 0, 0, -1, 1 };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        sc.nextLine();
        board = new char[H][W];
        int kingR = -1, kingC = -1;
        List<Integer> pawnsR = new ArrayList<>();
        List<Integer> pawnsC = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < W; j++) {
                board[i][j] = line.charAt(j);
                if (board[i][j] == 'k') {
                    kingR = i;
                    kingC = j;
                } else if (board[i][j] == 'p') {
                    pawnsR.add(i);
                    pawnsC.add(j);
                }
            }
        }

        // State: king top-left (r,c) + set of pawn positions as bitset
        // We'll encode pawn positions into a bitmask (max 36 cells, fits in long)
        int totalCells = H * W;
        long pawnMask = 0;
        for (int i = 0; i < pawnsR.size(); i++) {
            int idx = pawnsR.get(i) * W + pawnsC.get(i);
            pawnMask |= (1L << idx);
        }

        State start = new State(kingR, kingC, pawnMask);
        Queue<State> queue = new LinkedList<>();
        Map<State, Integer> dist = new HashMap<>();
        queue.add(start);
        dist.put(start, 0);

        while (!queue.isEmpty()) {
            State cur = queue.poll();
            int d = dist.get(cur);

            // Check if king at (0,0)
            if (cur.kr == 0 && cur.kc == 0) {
                System.out.println(d);
                return;
            }

            // Generate king moves
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.kr + dr[dir];
                int nc = cur.kc + dc[dir];
                if (nr < 0 || nr + 1 >= H || nc < 0 || nc + 1 >= W) continue;
                // Check that 2x2 area is free
                boolean free = true;
                long mask = cur.pawnMask;
                for (int i = 0; i < 2; i++) {
                    for (int j = 0; j < 2; j++) {
                        int idx = (nr + i) * W + (nc + j);
                        if ((mask & (1L << idx)) != 0) {
                            free = false;
                            break;
                        }
                    }
                    if (!free) break;
                }
                if (!free) continue;
                State next = new State(nr, nc, mask);
                if (!dist.containsKey(next)) {
                    dist.put(next, d + 1);
                    queue.add(next);
                }
            }

            // Generate pawn moves
            // For each pawn position in mask, try 4 directions
            long mask = cur.pawnMask;
            for (int cell = 0; cell < totalCells; cell++) {
                if ((mask & (1L << cell)) == 0) continue;
                int pr = cell / W;
                int pc = cell % W;
                for (int dir = 0; dir < 4; dir++) {
                    int nr = pr + dr[dir];
                    int nc = pc + dc[dir];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    int nIdx = nr * W + nc;
                    // Destination must be empty (not king area, not occupied by other pawn)
                    boolean occupiedByKing = (nr >= cur.kr && nr <= cur.kr + 1 && nc >= cur.kc && nc <= cur.kc + 1);
                    if (occupiedByKing) continue;
                    if ((mask & (1L << nIdx)) != 0) continue;
                    long newMask = mask ^ (1L << cell) ^ (1L << nIdx);
                    State next = new State(cur.kr, cur.kc, newMask);
                    if (!dist.containsKey(next)) {
                        dist.put(next, d + 1);
                        queue.add(next);
                    }
                }
            }
        }

        // Should never reach here if puzzle solvable
        System.out.println(-1);
    }

    static class State {
        int kr, kc;
        long pawnMask;
        State(int kr, int kc, long pawnMask) {
            this.kr = kr;
            this.kc = kc;
            this.pawnMask = pawnMask;
        }
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof State)) return false;
            State s = (State) o;
            return kr == s.kr && kc == s.kc && pawnMask == s.pawnMask;
        }
        @Override
        public int hashCode() {
            return Objects.hash(kr, kc, pawnMask);
        }
    }
}

