import java.io.*;
import java.util.*;

/*
 * Sliding blocks with obstacles:
 * - Board is rectangular.
 * - Obstacles are fixed blocked cells.
 * - One king piece of size 2x2.
 * - Several 1x1 pawns.
 * - A move: slide one piece by one cell orthogonally into empty space.
 * Goal: move the king so its top-left corner is at (0,0).
 *
 * We solve with BFS over states.
 *
 * Input format assumed:
 *   R C
 *   R lines of length C describing the board
 *
 * Characters:
 *   '#' = obstacle / wall
 *   '.' = empty
 *   'K' = cells occupied by the 2x2 king (exactly 4 cells)
 *   'P' = pawn (1x1)
 *
 * Output:
 *   minimum number of moves, or -1 if impossible.
 *
 * This is the natural interpretation of the statement. The BFS state stores:
 *   - king top-left position
 *   - sorted list of pawn positions
 *
 * Obstacles are static and not stored in the state.
 */
public class Main {
    static int R, C;
    static char[][] grid;
    static boolean[][] obstacle;

    static class State {
        int kr, kc;      // king top-left
        int[] pawns;     // sorted cell ids r*C+c

        State(int kr, int kc, int[] pawns) {
            this.kr = kr;
            this.kc = kc;
            this.pawns = pawns;
        }

        String encode() {
            StringBuilder sb = new StringBuilder();
            sb.append(kr).append(',').append(kc).append('|');
            for (int x : pawns) sb.append(x).append(',');
            return sb.toString();
        }
    }

    static boolean in(int r, int c) {
        return r >= 0 && r < R && c >= 0 && c < C;
    }

    static boolean[][] buildOccupied(State s) {
        boolean[][] occ = new boolean[R][C];

        // obstacles as occupied
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (obstacle[i][j]) occ[i][j] = true;
            }
        }

        // king
        for (int dr = 0; dr < 2; dr++) {
            for (int dc = 0; dc < 2; dc++) {
                occ[s.kr + dr][s.kc + dc] = true;
            }
        }

        // pawns
        for (int id : s.pawns) {
            occ[id / C][id % C] = true;
        }

        return occ;
    }

    static List<State> nextStates(State s) {
        List<State> res = new ArrayList<>();
        boolean[][] occ = buildOccupied(s);

        // move king
        int[] drs = {-1, 1, 0, 0};
        int[] dcs = {0, 0, -1, 1};

        for (int d = 0; d < 4; d++) {
            int nr = s.kr + drs[d];
            int nc = s.kc + dcs[d];
            if (nr < 0 || nc < 0 || nr + 1 >= R || nc + 1 >= C) continue;

            // remove current king cells temporarily
            for (int dr = 0; dr < 2; dr++) {
                for (int dc = 0; dc < 2; dc++) {
                    occ[s.kr + dr][s.kc + dc] = false;
                }
            }

            boolean ok = true;
            for (int dr = 0; dr < 2 && ok; dr++) {
                for (int dc = 0; dc < 2; dc++) {
                    if (occ[nr + dr][nc + dc]) {
                        ok = false;
                        break;
                    }
                }
            }

            // restore
            for (int dr = 0; dr < 2; dr++) {
                for (int dc = 0; dc < 2; dc++) {
                    occ[s.kr + dr][s.kc + dc] = true;
                }
            }

            if (ok) {
                res.add(new State(nr, nc, s.pawns.clone()));
            }
        }

        // move each pawn
        for (int i = 0; i < s.pawns.length; i++) {
            int id = s.pawns[i];
            int r = id / C, c = id % C;

            occ[r][c] = false; // remove this pawn temporarily
            for (int d = 0; d < 4; d++) {
                int nr = r + drs[d];
                int nc = c + dcs[d];
                if (!in(nr, nc)) continue;
                if (occ[nr][nc]) continue;

                int[] np = s.pawns.clone();
                np[i] = nr * C + nc;
                Arrays.sort(np);
                res.add(new State(s.kr, s.kc, np));
            }
            occ[r][c] = true;
        }

        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        while ((first = br.readLine()) != null && first.trim().isEmpty()) {}
        if (first == null) return;

        StringTokenizer st = new StringTokenizer(first);
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());

        grid = new char[R][C];
        obstacle = new boolean[R][C];

        List<Integer> kingCells = new ArrayList<>();
        List<Integer> pawns = new ArrayList<>();

        for (int i = 0; i < R; i++) {
            String line = br.readLine();
            while (line != null && line.length() < C) {
                String extra = br.readLine();
                if (extra == null) break;
                line += extra;
            }
            grid[i] = line.toCharArray();
            for (int j = 0; j < C; j++) {
                char ch = grid[i][j];
                if (ch == '#') obstacle[i][j] = true;
                else if (ch == 'K') kingCells.add(i * C + j);
                else if (ch == 'P') pawns.add(i * C + j);
            }
        }

        if (kingCells.size() != 4) {
            System.out.println(-1);
            return;
        }

        int minR = Integer.MAX_VALUE, minC = Integer.MAX_VALUE;
        boolean[][] hasKing = new boolean[R][C];
        for (int id : kingCells) {
            int r = id / C, c = id % C;
            hasKing[r][c] = true;
            minR = Math.min(minR, r);
            minC = Math.min(minC, c);
        }

        // validate king is exactly a 2x2 block
        boolean validKing = minR + 1 < R && minC + 1 < C
                && hasKing[minR][minC]
                && hasKing[minR + 1][minC]
                && hasKing[minR][minC + 1]
                && hasKing[minR + 1][minC + 1];

        if (!validKing) {
            System.out.println(-1);
            return;
        }

        int[] pawnArr = new int[pawns.size()];
        for (int i = 0; i < pawns.size(); i++) pawnArr[i] = pawns.get(i);
        Arrays.sort(pawnArr);

        State start = new State(minR, minC, pawnArr);

        Queue<State> q = new ArrayDeque<>();
        Queue<Integer> distQ = new ArrayDeque<>();
        HashSet<String> vis = new HashSet<>();

        q.add(start);
        distQ.add(0);
        vis.add(start.encode());

        while (!q.isEmpty()) {
            State cur = q.poll();
            int dist = distQ.poll();

            if (cur.kr == 0 && cur.kc == 0) {
                System.out.println(dist);
                return;
            }

            for (State nx : nextStates(cur)) {
                String key = nx.encode();
                if (vis.add(key)) {
                    q.add(nx);
                    distQ.add(dist + 1);
                }
            }
        }

        System.out.println(-1);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAXH 8
#define MAXW 8

int H, W;
char board[MAXH][MAXW+1];
int kr0, kc0; // initial king top-left
int pawn_count;
int pawn_r[64], pawn_c[64]; // positions of pawns initially

// cell index: idx = r*W + c
int cell_index(int r, int c) {
    return r*W + c;
}

uint64_t obstacle_mask = 0;
uint64_t king_mask(int kr, int kc) {
    uint64_t m = 0;
    m |= (1ULL << cell_index(kr, kc));
    m |= (1ULL << cell_index(kr+1, kc));
    m |= (1ULL << cell_index(kr, kc+1));
    m |= (1ULL << cell_index(kr+1, kc+1));
    return m;
}

int is_obstacle(int r, int c) {
    if (r<0||r>=H||c<0||c>=W) return 1;
    return board[r][c] == '#';
}

int main() {
    scanf("%d %d", &H, &W);
    for (int i=0; i<H; i++) {
        scanf("%s", board[i]);
    }
    // find initial positions
    pawn_count = 0;
    for (int r=0; r<H; r++) {
        for (int c=0; c<W; c++) {
            if (board[r][c] == '#') {
                obstacle_mask |= (1ULL << cell_index(r,c));
            } else if (board[r][c] == 'K') {
                kr0 = r; kc0 = c;
            } else if (board[r][c] == 'P') {
                pawn_r[pawn_count] = r;
                pawn_c[pawn_count] = c;
                pawn_count++;
            }
        }
    }
    // Build initial pawn mask
    uint64_t pawn_mask = 0;
    for (int i=0; i<pawn_count; i++) {
        pawn_mask |= (1ULL << cell_index(pawn_r[i], pawn_c[i]));
    }

    // BFS
    // visited: hash set of (kr,kc,mask) -> use a simple array if possible
    // Max states: (H-1)*(W-1)*2^(W*H) but we limit with dynamic allocation
    // We'll use a large hash table
    #define HASH_SIZE 1000003
    typedef struct {
        int kr, kc;
        uint64_t mask;
        int dist;
    } State;
    State queue[500000];
    int front=0, back=0;

    // visited marker
    int visited[HASH_SIZE];
    State* hash_table[HASH_SIZE];
    memset(hash_table, 0, sizeof(hash_table));
    memset(visited, 0, sizeof(visited));

    unsigned long long hash_key(int kr, int kc, uint64_t mask) {
        unsigned long long h = kr * 10007ULL + kc;
        h = h * 1000000007ULL + mask;
        return h % HASH_SIZE;
    }

    int insert_visited(int kr, int kc, uint64_t mask) {
        unsigned long long h = hash_key(kr, kc, mask);
        while (hash_table[h] != NULL) {
            if (hash_table[h]->kr == kr && hash_table[h]->kc == kc && hash_table[h]->mask == mask) {
                return 0; // already exists
            }
            h = (h+1) % HASH_SIZE;
        }
        // store
        State *s = malloc(sizeof(State));
        s->kr = kr; s->kc = kc; s->mask = mask;
        hash_table[h] = s;
        return 1;
    }

    // initial state
    queue[back].kr = kr0; queue[back].kc = kc0; queue[back].mask = pawn_mask; queue[back].dist = 0;
    back++;
    insert_visited(kr0, kc0, pawn_mask);

    int dr[4] = {-1,1,0,0};
    int dc[4] = {0,0,-1,1};

    while (front < back) {
        State cur = queue[front++];
        int kr = cur.kr, kc = cur.kc, dist = cur.dist;
        uint64_t mask = cur.mask;

        // goal?
        if (kr == 0 && kc == 0) {
            printf("%d\n", dist);
            return 0;
        }

        uint64_t king_area = king_mask(kr, kc);

        // 1) King moves
        for (int d=0; d<4; d++) {
            int nkr = kr + dr[d];
            int nkc = kc + dc[d];
            if (nkr < 0 || nkr+1 >= H || nkc < 0 || nkc+1 >= W) continue;
            uint64_t new_king_area = king_mask(nkr, nkc);
            // check obstacles
            if (new_king_area & obstacle_mask) continue;
            // check pawns
            if (new_king_area & mask) continue;
            // move king -> update mask (king area vacated, new area occupied by king? Actually king is not in mask, mask only for pawns. So no change to mask.)
            if (insert_visited(nkr, nkc, mask)) {
                queue[back].kr = nkr; queue[back].kc = nkc; queue[back].mask = mask; queue[back].dist = dist+1;
                back++;
            }
        }

        // 2) Pawn moves
        // find all pawn positions from mask
        uint64_t m = mask;
        while (m) {
            int bit = __builtin_ctzll(m);
            m &= (m-1);
            int r = bit / W;
            int c = bit % W;
            // try move this pawn
            for (int d=0; d<4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr<0||nr>=H||nc<0||nc>=W) continue;
                if (obstacle_mask & (1ULL << cell_index(nr,nc))) continue;
                if (king_area & (1ULL << cell_index(nr,nc))) continue; // king occupies
                if (mask & (1ULL << cell_index(nr,nc))) continue; // another pawn
                uint64_t new_mask = mask;
                new_mask &= ~(1ULL << cell_index(r,c));
                new_mask |= (1ULL << cell_index(nr,nc));
                if (insert_visited(kr, kc, new_mask)) {
                    queue[back].kr = kr; queue[back].kc = kc; queue[back].mask = new_mask; queue[back].dist = dist+1;
                    back++;
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
